INSERT INTO "PortfolioProject" SELECT * FROM json_populate_record(NULL::"PortfolioProject", '{"id":"cmvsckq65000bffyi7zmmh1f4","slug":"sample-social-content-system","title":"Sample: Monthly content system for a D2C brand","clientName":"Sample Client (replace me)","industry":"Consumer goods","serviceCategory":"SOCIAL_MEDIA_MANAGEMENT","categoryLabel":"Social Media","shortDescription":"Example structure for a social media retainer project: audit, content pillars, monthly calendar and reporting cadence.","overview":"This is sample content included with the initial build so you can see how a published project page is structured. Replace it with a real, authorised case study from the admin dashboard.\n\nThe engagement model shown here covers a channel audit, four content pillars, a monthly approval cycle and a reporting pack.","brief":"The brand published in bursts around product launches and had no repeatable production system. Content quality varied by whoever had capacity that week.","challenges":"No documented visual guidelines, no content calendar, and enquiry DMs going unanswered for several days.","strategy":"Define four content pillars mapped to customer questions, establish a visual system, and move to a single monthly approval cycle with batched production.","solution":"A 30-day calendar with static posts, carousels and short-form video, a shared asset library, comment and DM service hours, and a monthly performance review.","technologies":["Content calendar","Brand system","Short-form editing"],"deliverables":["Channel audit","Content pillars","Monthly calendar","Performance report"],"projectUrl":null,"launchDate":null,"serviceRef":"cmvsckq5t0001ffyi4kcyzi0s","featuredImage":"/media/project-social.jpg","featuredImageAlt":"A monthly social media content planner and a smartphone","featured":true,"status":"PUBLISHED","isSampleContent":true,"order":1,"seoTitle":"Sample: Monthly content system for a D2C brand","seoDescription":"Example structure for a social media retainer project: audit, content pillars, monthly calendar and reporting cadence.","createdAt":"2026-10-28T16:47:17.885","updatedAt":"2026-10-28T16:47:17.885"}'::json) ON CONFLICT DO NOTHING;
INSERT INTO "PortfolioProject" SELECT * FROM json_populate_record(NULL::"PortfolioProject", '{"id":"cmvsckq67000effyiiz5d4v5z","slug":"sample-shopify-storefront","title":"Sample: Shopify storefront for a growing catalogue","clientName":"Sample Client (replace me)","industry":"Retail","serviceCategory":"SHOPIFY_DEVELOPMENT","categoryLabel":"Shopify","shortDescription":"Example structure for a Shopify theme project: catalogue architecture, custom sections, product page design and performance work.","overview":"This is sample content included with the initial build so you can see how a published project page is structured. Replace it with a real, authorised case study from the admin dashboard.\n\nThe example covers a theme rebuild around a catalogue with variants and bundles, editable marketing sections and a mobile-first product page.","brief":"An existing theme could not present variants and bundles clearly, and the product page buried shipping and sizing information below the fold on mobile.","challenges":"Heavy app stack, large uncompressed imagery, and marketing changes blocked behind a developer queue.","strategy":"Rebuild the theme around a section library, restructure products with metafields, and set a performance budget before design started.","solution":"Custom Shopify theme with configurable sections, redesigned product page with sticky add-to-cart, compressed responsive imagery and tracked conversion events.","technologies":["Shopify Liquid","Tailwind CSS","Shopify CLI"],"deliverables":["Theme architecture","Product page design","Section library","Launch QA"],"projectUrl":null,"launchDate":null,"serviceRef":"cmvsckq5w0002ffyixhqsptk3","featuredImage":"/media/project-shopify.jpg","featuredImageAlt":"A laptop showing an online store beside packing boxes","featured":true,"status":"PUBLISHED","isSampleContent":true,"order":2,"seoTitle":"Sample: Shopify storefront for a growing catalogue","seoDescription":"Example structure for a Shopify theme project: catalogue architecture, custom sections, product page design and performance work.","createdAt":"2026-10-28T16:47:17.887","updatedAt":"2026-10-28T16:47:17.887"}'::json) ON CONFLICT DO NOTHING;
INSERT INTO "PortfolioProject" SELECT * FROM json_populate_record(NULL::"PortfolioProject", '{"id":"cmvsckq69000iffyig728anmg","slug":"sample-wordpress-business-site","title":"Sample: WordPress website for a professional services firm","clientName":"Sample Client (replace me)","industry":"Professional services","serviceCategory":"WORDPRESS_DEVELOPMENT","categoryLabel":"WordPress","shortDescription":"Example structure for a WordPress build: sitemap, reusable sections, editing roles and performance baseline.","overview":"This is sample content included with the initial build so you can see how a published project page is structured. Replace it with a real, authorised case study from the admin dashboard.\n\nThe example shows a rebuild where the primary goal was confident self-service editing plus a cleaner content hierarchy.","brief":"The team avoided updating the site because edits frequently broke layouts, so service pages drifted out of date.","challenges":"Nineteen active plugins doing structural work, inconsistent typography, and no documented editorial ownership.","strategy":"Reduce plugin dependency, build a reusable section library, and hand over an editor guide with clear roles.","solution":"A WordPress build with approved content blocks, structured service and insight sections, image optimisation, caching and editor training.","technologies":["WordPress","Elementor","Tailwind CSS"],"deliverables":["Sitemap","Section library","CMS setup","Editor training"],"projectUrl":null,"launchDate":null,"serviceRef":"cmvsckq5y0003ffyii57gcr7s","featuredImage":"/media/project-wordpress.jpg","featuredImageAlt":"A desktop monitor displaying a website in a bright workspace","featured":true,"status":"PUBLISHED","isSampleContent":true,"order":3,"seoTitle":"Sample: WordPress website for a professional services firm","seoDescription":"Example structure for a WordPress build: sitemap, reusable sections, editing roles and performance baseline.","createdAt":"2026-10-28T16:47:17.889"